import { DC } from "../../constants";

export function updateSpaceResearches(diff) {
  SpaceResearchRifts.all.forEach(r => r.fill(diff));
}

export function getBaseResearchSpeed() {
  const spaceFactor = DC.E1.pow(getEffectiveSpace().add(1).log10().add(1).pow(2.5).sub(1));
  const dbFactor = DC.D2.pow(DimBoost.totalBoosts.pow(0.75));

  let baseResearchSpeed = spaceFactor.mul(dbFactor);
  if (PlayerProgress.imaginaryUnlocked() && !AbyssResearches.C0.completed) {
    baseResearchSpeed = baseResearchSpeed.div(10).pow(0.9);
  }
  return baseResearchSpeed;
}

export function globalResearchSpeed() {
  const baseResearchSpeed = getBaseResearchSpeed();

  const researchFactor = SpaceResearchRifts.r21.effectValue[1]; // R21
  const achievementFactor = Achievements.power;
  let otherFactors = DC.D1.timesEffectsOf(
    InfinityUpgrade.totalTimeMult,
    TimeStudy(91),
    TimeStudy(92),
    TimeStudy(102),
    TimeStudy(222),
    AbyssResearches.A3,
    AbyssResearches.A22
  );
  if (isSCRunningOnTier(5, 1)) otherFactors = otherFactors.div(SpaceChallenge(5).effectValue);
  return baseResearchSpeed.mul(researchFactor).mul(achievementFactor).mul(otherFactors);
}

export function tierBasedResearchSpeed(tier) {
  let researchSpd = globalResearchSpeed();
  if (tier < 3) researchSpd = researchSpd.mul(light.blue.effectValue());
  switch (tier) {
    case 0:
      researchSpd = researchSpd.timesEffectsOf(InfinityUpgrade.dim18mult);
      break;
    case 1:
      researchSpd = researchSpd.timesEffectsOf(InfinityUpgrade.dim27mult);
      break;
    case 2:
      researchSpd = researchSpd.timesEffectsOf(InfinityUpgrade.dim36mult);
      break;
    case 3:
      researchSpd = researchSpd.timesEffectsOf(TimeStudy(32));
      break;
  }
  return researchSpd;
}

