import { DC } from "../../constants";

import { abyssResearch } from "./mod-research";

import { MultiplierTabIcons } from "./icons";

// See index.js for documentation
export const replicanti = {
  total: {
    name: "Replicanti Speed (including Slowdown, before V)",
    multValue: () => totalReplicantiSpeedMult(Replicanti.amount.gt(replicantiCap())).div(ReplicantiGrowth.slowdown),
    isActive: () => PlayerProgress.eternityUnlocked(),
    overlay: ["Ξ"],
  },
  achievement: {
    name: "Achievement 134",
    // This is explicitly 2 in the replicanti code as well, inside of a replicanti amount check
    multValue: 2,
    isActive: () => Achievement(134).canBeApplied && Replicanti.amount.lte(replicantiCap()) && !Pelle.isDoomed,
    icon: MultiplierTabIcons.ACHIEVEMENT,
  },
  timeStudy: {
    name: "Time Studies",
    multValue: () => {
      const preReality = Effects.product(TimeStudy(52)).mul(TimeStudy(21).isBought ? 1 / 3 : 1);
      return preReality;
    },
    isActive: () => PlayerProgress.eternityUnlocked() && !Pelle.isDoomed,
    icon: MultiplierTabIcons.TIME_STUDY,
  },
  SR52: {
    name: () => `Space Research r52 - Replicated Flux`,
    multValue: () => SpaceResearchRifts.r52.effectValue,
    isActive: () => SpaceResearchRifts.r52.canBeApplied,
    icon: MultiplierTabIcons.SPACE_RESEARCH(4),
  },
  A19: abyssResearch("A19", "Replicanti Speed"),
  slowdown: {
    name: "Slowdown above Replicanti Cap (before Future Empower)",
    multValue: () => Decimal.pow(ReplicantiGrowth.baseScaleFactor, ReplicantiGrowth.slowdownExponent.neg()),
    isActive: () => Replicanti.amount.gt(replicantiCap()),
    icon: MultiplierTabIcons.DIVISOR("Ξ"),
  },
  futureEmpower: {
    name: "Future Empower - Replicanti Slowdown Reduction",
    displayOverride: () => FutureEmpowerOrbs.replicanti.formattedEffect,
    // Show the recovered speed, not the root applied to the slowdown factor.
    multValue: () => Decimal.pow(ReplicantiGrowth.baseScaleFactor,
      ReplicantiGrowth.slowdownExponent.mul(Decimal.sub(1, Decimal.div(1, ReplicantiGrowth.slowdownReduction)))),
    isActive: () => FutureEmpowerOrbs.replicanti.canBeApplied && Replicanti.amount.gt(replicantiCap()) &&
      !Pelle.isDisabled("replicantiIntervalMult"),
    icon: MultiplierTabIcons.UPGRADE("reality"),
  },
  glyph: {
    name: "Glyph Effects",
    multValue: () => {
      const baseEffect = (Pelle.isDoomed ? DC.D1 : getAdjustedGlyphEffect("replicationspeed"))
        .times(Pelle.specialGlyphEffect.replication);
      const alteredEffect = Decimal.clampMin(
        Decimal.log10(Replicanti.amount).mul(getSecondaryGlyphEffect("replicationdtgain")), 1);
      return GlyphAlteration.isAdded("replication") ? baseEffect.times(alteredEffect) : baseEffect;
    },
    isActive: () => PlayerProgress.realityUnlocked() && (!Pelle.isDoomed || Pelle.specialGlyphEffect.replication > 1),
    icon: MultiplierTabIcons.GENERIC_GLYPH,
  },
  amplifierRep: {
    name: "Reality Upgrade - Replicative Amplifier",
    multValue: () => RealityUpgrade(2).effectOrDefault(1),
    isActive: () => PlayerProgress.realityUnlocked() && !Pelle.isDoomed,
    icon: MultiplierTabIcons.UPGRADE("reality"),
  },
  realityUpgrade1: {
    name: "Reality Upgrade - Cosmically Duplicate",
    multValue: () => RealityUpgrade(6).effectOrDefault(1),
    isActive: () => PlayerProgress.realityUnlocked() && !Pelle.isDoomed,
    icon: MultiplierTabIcons.UPGRADE("reality"),
  },
  realityUpgrade2: {
    name: "Reality Upgrade - Replicative Rapidity",
    multValue: () => RealityUpgrade(23).effectOrDefault(1),
    isActive: () => PlayerProgress.realityUnlocked() && !Pelle.isDoomed,
    icon: MultiplierTabIcons.UPGRADE("reality"),
  },
  alchemy: {
    name: "Alchemy Resource - Replication",
    multValue: () => AlchemyResource.replication.effectOrDefault(1),
    isActive: () => Ra.unlocks.unlockGlyphAlchemy.canBeApplied && !Pelle.isDoomed,
    icon: MultiplierTabIcons.ALCHEMY,
  },
  ra: {
    name: "Ra Upgrade - Multiplier based on TT",
    multValue: () => Ra.unlocks.continuousTTBoost.effects.replicanti.effectOrDefault(1),
    isActive: () => Ra.unlocks.continuousTTBoost.isUnlocked,
    icon: MultiplierTabIcons.GENERIC_RA,
  },
  pelle: {
    name: "Pelle Strike - Decay Rift",
    multValue: () => PelleRifts.decay.effectValue,
    isActive: () => Pelle.isDoomed && PelleRifts.decay.effectValue.gt(1),
    icon: MultiplierTabIcons.PELLE,
  },
  iap: {
    name: "Shop Tab Purchases",
    multValue: () => 1,
    isActive: () => false,
    icon: MultiplierTabIcons.IAP,
  },
  prism: {
    name: () => `Prism nerf to Replicanti`,
    multValue: () => getPrismReplicantiNerf().recip(),
    isActive: () => getPrismReplicantiNerf().neq(1),
    icon: MultiplierTabIcons.SPACE_RESEARCH(4),
  },
};
